import { queryStringParams } from '../..';
import { Injects } from '../..';
import { PrizeLeagueManager } from '../../services/prize-league/prize-league-manager';
import { inversifyContainer } from '../../inversify/container';
import { IUserData } from '../../services/prize-league/types';

/** Skin name used for theming across all prize league components */
export function getPrizeLeagueSkinName(): string {
    return queryStringParams.launchedFrom || 'arcade';
}

/** Resolves the PrizeLeagueManager from the inversify container */
export function getPrizeLeagueManager(): PrizeLeagueManager {
    return inversifyContainer.get<PrizeLeagueManager>(Injects.PrizeLeagueManager);
}

/** Returns ordinal suffix for a number (1st, 2nd, 3rd, 4th, etc.) */
export function getOrdinalSuffix(n: number): string {
    const lastTwo = n % 100;
    if (lastTwo >= 11 && lastTwo <= 13) return 'th';
    if (n % 10 === 1) return 'st';
    if (n % 10 === 2) return 'nd';
    if (n % 10 === 3) return 'rd';
    return 'th';
}

/** Adds positionDisplay (e.g. "1st", "2nd") to a IUserData object */
export function enrichUserData(user: IUserData): IUserData {
    user.positionDisplay = user.position ? `${user.position}${getOrdinalSuffix(user.position)}` : '--';
    user.username = truncateUsername(user.username);
    return user;
}

/** Truncates a username to 12 characters with ellipsis if longer */
export function truncateUsername(name: string): string {
    return name.length > 12 ? name.slice(0, 12) + '...' : name;
}

/** Formats a date (or date string) into a readable format e.g. "5th January, 2:30 pm" */
export function formatDate(date: Date | string): string {
    const d = typeof date === 'string' ? new Date(date) : date;
    const day = d.getDate();
    const suffix = getOrdinalSuffix(day);
    const month = d.toLocaleDateString('en-GB', { month: 'long' });
    const hour = d.getHours();
    const hour12 = hour % 12 === 0 ? 12 : hour % 12;
    const min = d.getMinutes().toString().padStart(2, '0');
    const ampm = hour < 12 ? 'am' : 'pm';
    return `${day}${suffix} ${month}, ${hour12}:${min} ${ampm}`;
}
